-- Ajouts contrôlés 22/11/2026, après publication du Conseiller.
-- Aucune somme, aucun droit acquis, aucune permanence ou disponibilité garantie.
-- Statut a_reconfirmer lorsque seul un annuaire ancien (2023-2025) documente l'organisme.
DO $seed$
DECLARE r record;
BEGIN
  PERFORM pg_advisory_xact_lock(84690123);
  LOCK TABLE public.aides_reunion IN SHARE ROW EXCLUSIVE MODE;
  PERFORM setval(pg_get_serial_sequence('public.aides_reunion','id'),GREATEST((SELECT COALESCE(max(id),1) FROM public.aides_reunion),(SELECT last_value FROM public.aides_reunion_id_seq)),true);
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"nom":"SAPEX ADIL/ESF Réunion — prévention des expulsions locatives","categorie":"logement","organisme":"ADIL de La Réunion et ESF Réunion","type_dispositif":"service_gratuit","zone_couverte":"La Réunion","commune":null,"description_fr":"Le SAPEX accompagne les ménages confrontés à des impayés de loyer : conseil sociojuridique, appui social et recherche de solutions pour éviter une expulsion. L''ADIL publie une plateforme gratuite « Allo ! Loyers impayés 974 », au 0 800 000 234. L''accompagnement ne garantit ni effacement de dette, ni maintien dans le logement.","demarches_fr":"Contacter l''ADIL ou le 0 800 000 234 pour exposer les impayés et demander une évaluation sociojuridique. En cas de procédure, contacter rapidement le bailleur et le service social.","lien":"https://www.anil.org/adil-974/notre-expertise/le-pole-social/","statut":"source_confirmee","periode":"Service décrit sur le site de l''ADIL. Horaires du numéro et capacité à confirmer au moment de l''appel.","score":98},{"nom":"ALEFPA — accompagnement vers et dans le logement (AVDL)","categorie":"logement","organisme":"ALEFPA","type_dispositif":"accompagnement","zone_couverte":"La Réunion, orientation selon situation et dispositif","commune":"Saint-Pierre","description_fr":"L''AVDL d''ALEFPA apporte un accompagnement social individualisé pour l''accès, le maintien ou le relogement, notamment après hébergement d''urgence, après une décision DALO ou pour des ménages touchés par l''habitat indigne. Les parcours dépendent d''une orientation et d''une évaluation ; aucune place ne peut être garantie.","demarches_fr":"Demander à son travailleur social, son CCAS ou sa boutique solidarité une évaluation et, si pertinent, une orientation vers l''AVDL ALEFPA ; consulter la fiche officielle de la structure pour ses coordonnées.","lien":"https://www.alefpa.fr/etablissement/intermediation-locative-iml-accompagnement-vers-et-dans-le-logement-avdl/","statut":"source_confirmee","periode":"Fiche de l''association consultée en novembre 2026 ; conditions d''orientation et moyens disponibles à vérifier.","score":94},{"nom":"SOLIKAZ — intermédiation locative et accompagnement social","categorie":"logement","organisme":"SOLIKAZ (portée par ADIL Réunion)","type_dispositif":"orientation","zone_couverte":"La Réunion, selon secteur et partenaires","commune":null,"description_fr":"SOLIKAZ anime un réseau réunionnais de structures d''intermédiation locative, soutenu par l''État et porté par l''ADIL. Il relie propriétaires, opérateurs et accompagnement des locataires dans la gestion locative sociale ; ce n''est pas un guichet de logement attribué immédiatement.","demarches_fr":"Consulter le réseau de partenaires SOLIKAZ et faire étudier le besoin d''intermédiation locative par un travailleur social ou un opérateur ; vérifier l''activité des partenaires avant d''orienter.","lien":"https://solikaz.re/","statut":"a_reconfirmer","periode":"Réseau décrit sur son site ; nombre de partenaires et disponibilité des logements non vérifiés individuellement en novembre 2026.","score":82},{"nom":"ADILSS-CGL — défense des droits des locataires à La Réunion","categorie":"logement","organisme":"ADILSS — Association de défense des intérêts des locataires","type_dispositif":"accompagnement","zone_couverte":"La Réunion, représentation locataires et locataires sociaux","commune":"Saint-Denis","description_fr":"Association de défense collective des intérêts des locataires, affiliée à la Confédération générale du logement. Son site présente des actions d''information, de solidarité et de représentation auprès des bailleurs sociaux ; ses permanences actuelles doivent être confirmées. Ne pas confondre avec l''ADIL 974, organisme public de conseil.","demarches_fr":"Consulter le site de l''ADILSS, contacter l''association et demander si elle accompagne actuellement les difficultés de bail, charges ou représentation des locataires dans sa commune.","lien":"https://www.adilss.re/","statut":"a_reconfirmer","periode":"Site associatif consulté en 2026, dernières actualités repérées en 2024 ; services et permanences 2026 à confirmer.","score":85},{"nom":"KAL 974 — Kolèktif des associations pour le logement","categorie":"logement","organisme":"Kolèktif des Associations pour le Logement (KAL 974)","type_dispositif":"orientation","zone_couverte":"La Réunion","commune":null,"description_fr":"Collectif réunionnais constitué en 2026, regroupant plusieurs organismes sans but lucratif engagés contre l''exclusion liée au logement et pour l''accompagnement des personnes mal logées. Il fédère des acteurs : le collectif ne garantit pas un logement ni une allocation.","demarches_fr":"Consulter les organismes membres du collectif et demander une orientation au service social ou à une association membre selon la commune et la situation de logement.","lien":"https://www.kal974.org/qui-sommes-nous/","statut":"source_confirmee","periode":"Création et membres annoncés en 2026 ; accompagnement et accueil à vérifier individuellement auprès des partenaires.","score":87},{"nom":"Kap Konèk.T — inclusion numérique avec la Région Réunion","categorie":"administratif","organisme":"Région Réunion et partenaires d''inclusion numérique","type_dispositif":"accompagnement","zone_couverte":"La Réunion, ateliers dans les points partenaires selon calendrier","commune":null,"description_fr":"Programme régional d''inclusion numérique lancé fin 2025 et actualisé en octobre 2026, visant notamment les seniors, demandeurs d''emploi, familles modestes et jeunes en insertion pour apprendre les démarches en ligne, la communication et l''accès aux droits. Les points d''accueil et ateliers dépendent des partenaires.","demarches_fr":"Consulter le programme Kap Konèk.T de la Région et demander à une structure partenaire ou France Services de sa commune s''il existe actuellement un atelier accessible ; vérifier le calendrier.","lien":"https://www.regionreunion.com/actualites/kap-konek-t-nouveau-dispositif-regional-pour-linclusion-numerique-a-la-reunion/","statut":"source_confirmee","periode":"Annonce du 03/12/2025 actualisée le 24/10/2026 ; ateliers et disponibilité à confirmer.","score":89},{"nom":"Maison des femmes MFME — antenne Ouest à Saint-Paul","categorie":"social","organisme":"CHOR — Maison des femmes, de la mère et de l''enfant","type_dispositif":"accompagnement","zone_couverte":"Ouest de La Réunion","commune":"Saint-Paul","description_fr":"L''antenne Ouest de la Maison des femmes, de la mère et de l''enfant propose une prise en charge médicale, psychologique et sociale aux personnes victimes de violences, actuelles ou passées. Cette structure ne remplace pas les secours en cas de danger immédiat.","demarches_fr":"Consulter la fiche de l''Observatoire réunionnais des violences faites aux femmes pour les contacts de l''antenne Ouest, puis solliciter une orientation. En cas de danger immédiat, appeler le 17 ou 112.","lien":"https://orviff.re/annuaire/maison-des-femmes-de-la-mere-et-de-lenfant-mfme-antenne-ouest/","statut":"source_confirmee","periode":"Structure recensée par ORViFF. Horaires, admission et modalités de rendez-vous à confirmer.","score":94},{"nom":"3A 974 — association des aidants et aidés","categorie":"senior","organisme":"Association des Aidants et Aidés 974 (3A 974)","type_dispositif":"orientation","zone_couverte":"La Réunion selon actions de l''association","commune":"Saint-Pierre","description_fr":"Association des aidants et aidés référencée par le service public national des personnes âgées dans le répertoire réunionnais. Les services proposés, permanences et conditions d''accueil ne sont pas détaillés de manière récente sur la fiche.","demarches_fr":"Consulter la fiche dans l''annuaire public des associations et contacter directement la structure pour savoir si elle propose actuellement écoute, orientation ou soutien aux aidants.","lien":"https://www.pour-les-personnes-agees.gouv.fr/annuaire-association-parents-usagers-familles-soutien/la-reunion-974","statut":"a_reconfirmer","periode":"Présence dans l''annuaire gouvernemental consulté en novembre 2026 ; fiche source mise à jour en janvier 2025, activités actuelles inconnues.","score":76},{"nom":"Association des Sourds de La Réunion — entraide et représentation","categorie":"handicap","organisme":"Association des Sourds de La Réunion","type_dispositif":"orientation","zone_couverte":"La Réunion selon actions","commune":"Saint-Denis","description_fr":"Association des personnes sourdes référencée par l''annuaire public national pour les personnes âgées et aidants à La Réunion. Elle constitue une piste de contact pour la communauté sourde, sans affirmation sur des prestations ou permanences actuelles.","demarches_fr":"Rechercher les coordonnées dans l''annuaire public et demander quelles activités d''information, d''entraide ou de représentation sont toujours accessibles.","lien":"https://www.pour-les-personnes-agees.gouv.fr/annuaire-association-parents-usagers-familles-soutien/la-reunion-974","statut":"a_reconfirmer","periode":"Fiche ancienne (2023) encore listée en 2026 ; existence et accueil actuels à revérifier.","score":71},{"nom":"Hauts les Mains — association ressource à Saint-Pierre","categorie":"handicap","organisme":"Association Hauts les Mains","type_dispositif":"orientation","zone_couverte":"Saint-Pierre et autres actions éventuelles selon activité","commune":"Saint-Pierre","description_fr":"Association nommée dans l''annuaire officiel des associations de soutien de La Réunion, avec implantation à Saint-Pierre. La source ne décrit pas précisément ses services actuels : ne pas lui attribuer une aide financière ou un accompagnement spécialisé sans contrôle.","demarches_fr":"Consulter l''annuaire national pour ses coordonnées et contacter l''association pour demander son champ d''intervention actuel et les modalités d''accueil.","lien":"https://www.pour-les-personnes-agees.gouv.fr/annuaire-association-parents-usagers-familles-soutien/la-reunion-974","statut":"a_reconfirmer","periode":"Annuaire national : données de 2025 ; aucun service précis confirmé en novembre 2026.","score":70},{"nom":"ARPEDA Réunion — familles d''enfants déficients auditifs","categorie":"handicap","organisme":"Association Réunionnaise de Parents d''Enfants Déficients Auditifs (ARPEDA)","type_dispositif":"orientation","zone_couverte":"La Réunion, actions et permanences à confirmer","commune":"Saint-Pierre","description_fr":"Association de parents d''enfants déficients auditifs présente dans l''annuaire gouvernemental de La Réunion. Sa présence est documentée, mais ses services récents doivent être vérifiés directement auprès de l''association.","demarches_fr":"Rechercher l''association dans l''annuaire public, la contacter et demander les rencontres, informations ou accompagnements actuellement proposés aux familles.","lien":"https://www.pour-les-personnes-agees.gouv.fr/annuaire-association-parents-usagers-familles-soutien/la-reunion-974","statut":"a_reconfirmer","periode":"Annuaire public : fiche ancienne (2023) ; activité 2026 non confirmée.","score":74},{"nom":"Comité Valentin Haüy Réunion — soutien déficience visuelle","categorie":"handicap","organisme":"Association Valentin Haüy — comité Réunion et Océan Indien","type_dispositif":"orientation","zone_couverte":"La Réunion, actions du comité territorial","commune":"Saint-Pierre","description_fr":"Comité territorial de l''association Valentin Haüy figurant dans l''annuaire gouvernemental réunionnais, susceptible d''informer et d''orienter des personnes déficientes visuelles. Les services localement disponibles doivent être vérifiés.","demarches_fr":"Consulter la fiche de l''association et contacter le comité régional pour connaître les actions, aides techniques et activités accessibles actuellement, sans présumer de leur gratuité.","lien":"https://www.pour-les-personnes-agees.gouv.fr/annuaire-association-parents-usagers-familles-soutien/la-reunion-974","statut":"a_reconfirmer","periode":"Fiche source 2024 ; activité du comité et modalités 2026 à revalider.","score":80},{"nom":"MND&CO — collectif d''aidants de maladies neurodégénératives","categorie":"sante","organisme":"Collectif MND&CO","type_dispositif":"orientation","zone_couverte":"La Réunion, selon activité","commune":"L''Étang-Salé","description_fr":"Collectif MND&CO recensé à L''Étang-Salé par l''annuaire public des associations de soutien aux personnes âgées. Les actions actuelles d''entraide ou d''information doivent être précisées directement auprès du collectif.","demarches_fr":"Consulter les coordonnées du collectif dans l''annuaire et lui demander ses services actuels ; ne pas promettre une permanence ou une prestation.","lien":"https://www.pour-les-personnes-agees.gouv.fr/annuaire-association-parents-usagers-familles-soutien/la-reunion-974","statut":"a_reconfirmer","periode":"Annuaire : fiche de 2023, coordonnées et accueil à revérifier.","score":75},{"nom":"Planning familial 974 — information santé sexuelle et droits","categorie":"sante","organisme":"Planning Familial 974","type_dispositif":"orientation","zone_couverte":"La Réunion, accueil selon permanences","commune":"Saint-Louis","description_fr":"Association réunionnaise recensée parmi les ressources en santé sexuelle et dans les réseaux d''accompagnement face aux violences. Elle peut constituer un premier contact pour s''informer et être orienté ; horaires et prestations exactes non garantis.","demarches_fr":"Consulter l''annuaire Sextuoze pour les coordonnées actualisées, puis contacter le Planning Familial 974 avant de se déplacer. En danger immédiat, appeler le 17 ou 112.","lien":"https://www.sextuoze.re/structures-et-personnes-ressources-la-reunion","statut":"source_confirmee","periode":"Annuaire thématique consulté en 2026 ; modalités locales et permanences à vérifier.","score":91},{"nom":"UFR — Union des Femmes Réunionnaises, écoute et orientation","categorie":"social","organisme":"Union des Femmes Réunionnaises (UFR)","type_dispositif":"orientation","zone_couverte":"La Réunion, selon antennes","commune":"Saint-Paul","description_fr":"L''Union des Femmes Réunionnaises apparaît dans l''annuaire local d''écoute et d''orientation lié à la prévention des violences. Les permanences et accompagnements de 2026 doivent être confirmés avec l''association.","demarches_fr":"Consulter l''annuaire Sextuoze puis contacter l''UFR pour connaître les services et les lieux d''accueil. En danger immédiat, contacter le 17 ou 112.","lien":"https://www.sextuoze.re/autres-contacts","statut":"a_reconfirmer","periode":"Association référencée, permanence actuelle non vérifiée.","score":82},{"nom":"Allons Déor — PALI Réunion, coordination logement","categorie":"logement","organisme":"Association Allons Déor / PALI Réunion","type_dispositif":"orientation","zone_couverte":"La Réunion, après orientation des partenaires","commune":null,"description_fr":"L''association Allons Déor est nommée par le SIAO dans les ressources du dispositif PALI, orienté vers la coordination des parcours sociaux, médico-sociaux et sanitaires pour l''accès ou le maintien dans le logement. Il ne garantit pas un logement vacant ou une entrée directe.","demarches_fr":"Consulter la fiche PALI sur le site du SIAO et passer par un travailleur social ou le réseau partenaire pour demander une évaluation de la situation.","lien":"https://siao974.re/ressources-du-territoire/pali-reunion-inclusion-coordination-logement/","statut":"source_confirmee","periode":"Structure citée parmi les partenaires du SIAO ; disponibilité et conditions de prise en charge à confirmer.","score":85},{"nom":"CAP ADO Ouest — Maison des adolescents et soutien aux jeunes","categorie":"jeunesse","organisme":"Maison des Adolescents de l''Ouest / CAP ADO","type_dispositif":"accompagnement","zone_couverte":"Ouest de La Réunion, zones et publics à vérifier","commune":"Saint-Paul","description_fr":"Ressource d''écoute et d''orientation à destination des adolescents et de leurs familles, recensée dans la carte locale des structures de santé et de vie affective Sextuoze. La source ne garantit pas une consultation immédiate ni tous les publics.","demarches_fr":"Consulter la fiche locale Sextuoze pour les coordonnées de CAP ADO et contacter la Maison des adolescents pour connaître les modalités d''accueil, les âges et les horaires.","lien":"https://www.sextuoze.re/structures-et-personnes-ressources-la-reunion","statut":"a_reconfirmer","periode":"Structure référencée dans un annuaire local ; conditions et horaires d''accueil 2026 non confirmés.","score":89}]'::jsonb) AS x(
      nom text,categorie text,organisme text,type_dispositif text,zone_couverte text,commune text,
      description_fr text,demarches_fr text,lien text,statut text,periode text,score integer
  ) LOOP
     IF NOT EXISTS (SELECT 1 FROM public.aides_reunion a WHERE lower(btrim(a.nom))=lower(btrim(r.nom)))
     THEN
        INSERT INTO public.aides_reunion (
         nom,categorie,commune,organisme,type_dispositif,zone_couverte,
         description,description_fr,description_kreol,demarches_fr,demarches_kreol,
         lien,lien_officiel,source_verification,date_verification,periode_validite,
         statut_verification,score_priorite,actif
        ) VALUES (
         r.nom,r.categorie,r.commune,r.organisme,r.type_dispositif,r.zone_couverte,
         r.description_fr,r.description_fr,
         'Organism-la lé dann in annuaire ou source publique. Kontak a zot pou vérifi kossa zot i fé.',
         r.demarches_fr,
         'Avan déplac aou, contacte l association ou service pou vérifi horaires et conditions.',
         r.lien,r.lien,r.lien,DATE '2026-11-22',r.periode,
         r.statut,r.score,true);
     END IF;
  END LOOP;
END
$seed$;
SELECT count(*) as total,count(*) filter(where actif) actives,max(id) max_id FROM public.aides_reunion;